46	export function formatCedenteInvalidFieldSummary(paths: string[], maxLabels = 4): string {
47	    const labels = paths.map(getCedenteFieldLabel);
48	    const unique = Array.from(new Set(labels));
49	    if (unique.length <= maxLabels) return unique.join(', ');
50	    return `${unique.slice(0, maxLabels).join(', ')} e mais ${unique.length - maxLabels}`;
51	}
