63	export function buildCedenteValidationFailureView(errors: FieldErrors) {
64	    const invalidPaths = flattenInvalidFieldPaths(errors);
65	    const fallbackPaths = Object.keys(errors);
66	    const paths = invalidPaths.length > 0 ? invalidPaths : fallbackPaths;
67	    const invalidCount = paths.length;
68	    const firstPath = paths[0];
69	    const labelSummary = formatCedenteInvalidFieldSummary(paths);
70	    const invalidFieldLabels = paths.map(getCedenteFieldLabel);
71	    const title = `${capitalizeFirstLetter(numberToWords(invalidCount))} ${invalidCount === 1 ? 'campo precisa' : 'campos precisam'} de correção`;
72	
73	    return {
74	        paths,
75	        firstPath,
76	        invalidCount,
77	        labelSummary,
78	        invalidFieldLabels,
79	        title,
80	    };
81	}
